// Hyperliquid trading tests.
//
// The signing core is pinned against GOLDEN VECTORS GENERATED BY THE
// OFFICIAL hyperliquid-python-sdk (hyperliquid.utils.signing) with a
// fixed key and nonce — not against this file's own implementation.
// If a signature here ever diverges from the SDK's, the exchange
// would recover a different signer and reject every action, so these
// assertions are the contract.
//   key 0x1111… → 0x19E7E376E7C213B7E7e7e46cc70A5dD086DAff2A
//   agent key 0x2222… → 0x1563915e194D8CfBA1943570603F7606A3115508
import assert from 'node:assert';
import { ethers } from 'ethers';
import {
  floatToWire, hlActionHash, hlSignL1Action, hlRecoverL1Signer,
  hlBuildApproveAgent, hlSignApproveAgent, hlRecoverApproveAgentSigner,
  hlOrderWire, hlOrderAction, hlUpdateLeverageAction, hlCancelAction,
  hlAssetId, hlRoundPrice, hlRoundSize, hlEstLiqPx,
} from '../client/lib/hl';

const MASTER_PK = '0x' + '11'.repeat(32);
const MASTER_ADDR = '0x19E7E376E7C213B7E7e7e46cc70A5dD086DAff2A';
const AGENT_ADDR = '0x1563915e194D8CfBA1943570603F7606A3115508';
const NONCE = 1700000000000;

// --- float_to_wire (SDK samples) ---
assert.equal(floatToWire(60000.5), '60000.5');
assert.equal(floatToWire(0.01), '0.01');
assert.equal(floatToWire(1.0), '1');
assert.equal(floatToWire(0.00001), '0.00001');
assert.equal(floatToWire(123.45678901), '123.45678901');
assert.equal(floatToWire(10.10), '10.1');
assert.equal(floatToWire(0.5), '0.5');
assert.equal(floatToWire(0), '0');
assert.throws(() => floatToWire(0.123456789012), /rounding/, 'unrepresentable float is refused, never silently rounded');

// --- asset ids (official formula) ---
assert.equal(hlAssetId(0, 0), 0, 'main dex BTC = 0');
assert.equal(hlAssetId(0, 159), 159, 'main dex = universe index');
assert.equal(hlAssetId(1, 12), 110012, 'HIP-3: 100000 + 1*10000 + 12 (docs example shape)');
assert.equal(hlAssetId(10, 1), 200001, 'HIP-3 dex at perpDexs index 10');

// --- order action: SDK wire shape + hash + signature ---
const wire = hlOrderWire({ asset: 0, isBuy: true, px: 60000.5, sz: 0.01, reduceOnly: false, tif: 'Gtc' });
assert.deepEqual(Object.keys(wire), ['a', 'b', 'p', 's', 'r', 't'], 'order wire field order matches the SDK (msgpack order is signed)');
const orderAction = hlOrderAction([wire]);
assert.deepEqual(Object.keys(orderAction), ['type', 'orders', 'grouping']);
assert.equal(
  hlActionHash(orderAction, NONCE),
  '0x893d57f7d8b87d22b118b92eb3b9a977a62381629e5556900f1647618eb5a561',
  'action hash matches the Python SDK byte for byte',
);
const orderSig = await hlSignL1Action(MASTER_PK, orderAction, NONCE, true);
assert.deepEqual(orderSig, {
  r: '0xea153587ba4aa5c2b6727c40450e0988befe3089ab258872d6ac7cc2e9a7a5b0',
  s: '0x30cb9a0913f71990ceb7db90e6c743c7faf3e6075e5823bd4eb3f45dbc9260d4',
  v: 28,
}, 'L1 order signature matches the Python SDK golden vector');
assert.equal(hlRecoverL1Signer(orderAction, orderSig, NONCE, true), MASTER_ADDR, 'signature recovers to the signer');
// Tampering with any signed field must break recovery.
const tampered = hlOrderAction([hlOrderWire({ asset: 0, isBuy: true, px: 60000.5, sz: 0.02, reduceOnly: false, tif: 'Gtc' })]);
assert.notEqual(hlRecoverL1Signer(tampered, orderSig, NONCE, true), MASTER_ADDR, 'tampered size no longer recovers to the signer');
assert.notEqual(hlRecoverL1Signer(orderAction, orderSig, NONCE + 1, true), MASTER_ADDR, 'wrong nonce no longer recovers to the signer');
assert.notEqual(hlRecoverL1Signer(orderAction, orderSig, NONCE, false), MASTER_ADDR, 'testnet phantom source differs from mainnet');

// --- updateLeverage + cancel golden signatures ---
const levAction = hlUpdateLeverageAction(3, true, 5);
assert.equal(hlActionHash(levAction, NONCE), '0x90f4a0173d6e1c9c1dd6a1ad0bcd3ae5c8bbd3edc06af5892d29010157aa8d27', 'updateLeverage hash matches SDK');
assert.deepEqual(await hlSignL1Action(MASTER_PK, levAction, NONCE, true), {
  r: '0x9689082cf9544a4dfe2fade36fe9a9f831a7b9646c39059b234dd938703fb602',
  s: '0x2b8c9ce735be054922cfb9b8991ef79e3f4a24ad582452dd010e82d8f1051652',
  v: 28,
}, 'updateLeverage signature matches SDK');
const cxlAction = hlCancelAction([{ a: 0, o: 77738308 }]);
assert.deepEqual(await hlSignL1Action(MASTER_PK, cxlAction, NONCE, true), {
  r: '0x3986d56d1ab47591cb36a259d0d3d912538e9dac40ce0971da65ebcef560c138',
  s: '0x2fc8ac319585fe8df01871cd7b4e62b389614bf2510b0e0c7fc9aea0abd22d3c',
  v: 28,
}, 'cancel signature matches SDK');

// --- approveAgent (user-signed) golden signature ---
const approve = hlBuildApproveAgent(AGENT_ADDR, 'Syn Wallet', NONCE, true);
assert.equal(approve.agentAddress, AGENT_ADDR.toLowerCase(), 'agent address is lowercased before signing (docs guidance)');
assert.equal(approve.signatureChainId, '0x66eee', 'signatureChainId is the SDK value for user-signed actions');
assert.equal(approve.hyperliquidChain, 'Mainnet');
const approveSig = await hlSignApproveAgent(MASTER_PK, approve);
assert.deepEqual(approveSig, {
  r: '0x2eeb5da61e20dd3f29e01e39342f072e27e5a24a6e38e137b844cf9d3a5b526a',
  s: '0x2eab2298599e917ef0c46aac302a4d2bae9d68e1832956521f6f323b3e40d48a',
  v: 28,
}, 'approveAgent signature matches the Python SDK golden vector');
assert.equal(hlRecoverApproveAgentSigner(approve, approveSig), MASTER_ADDR, 'approveAgent signature recovers to the master');
const approveTestnet = hlBuildApproveAgent(AGENT_ADDR, 'Syn Wallet', NONCE, false);
assert.equal(approveTestnet.hyperliquidChain, 'Testnet');
assert.notEqual(hlRecoverApproveAgentSigner(approveTestnet, approveSig), MASTER_ADDR, 'mainnet approval cannot be replayed on testnet');

// --- trigger (TP/SL) wire shape ---
const trig = hlOrderWire({ asset: 0, isBuy: false, px: 55000, sz: 0.01, reduceOnly: true, trigger: { isMarket: true, triggerPx: 55000, tpsl: 'sl' } });
assert.deepEqual(trig.t, { trigger: { isMarket: true, triggerPx: '55000', tpsl: 'sl' } }, 'trigger order wire matches SDK order_type_to_wire');
assert.deepEqual(Object.keys((trig.t as any).trigger), ['isMarket', 'triggerPx', 'tpsl'], 'trigger field order matches the SDK');

// --- price/size rounding rules ---
assert.equal(hlRoundPrice(61628.44, 5), 61628, 'BTC (szDecimals 5): 1 decimal max, 5 sig figs');
assert.equal(hlRoundPrice(0.123456, 2), 0.1235, 'szDecimals 2: 4 decimals max');
assert.equal(hlRoundPrice(3012.3456, 4), 3012.3, 'szDecimals 4: 2 decimals max, 5 sig figs');
assert.equal(hlRoundSize(0.1239, 2, 'down'), 0.12, 'size floors at szDecimals when asked');
assert.equal(hlRoundSize(0.1239, 2, 'round'), 0.12);
assert.equal(hlRoundSize(1.005, 1), 1, 'size rounds at szDecimals');

// --- liquidation estimate ---
assert.ok(Math.abs(hlEstLiqPx(100, true, 10, 50) - 91) < 1e-9, 'long 10x, maxLev 50 → est liq 91');
assert.ok(Math.abs(hlEstLiqPx(100, false, 10, 50) - 109) < 1e-9, 'short 10x, maxLev 50 → est liq 109');
assert.ok(hlEstLiqPx(100, true, 1, 50) < 2, '1x long liquidation is near zero');

console.log('HL TESTS PASSED');
